package practice;

import java.util.function.Supplier;

/**
 * The tenant whose data the current job may touch. The billing service runs its jobs on a shared
 * thread pool; repositories call TenantContext.current() to pick the tenant's schema.
 */
public final class TenantContext {

    private static final ThreadLocal<String> TENANT = new ThreadLocal<>();

    private TenantContext() {
    }

    /** The tenant of the job running on this thread, or null outside any job. */
    public static String current() {
        return TENANT.get();
    }

    /** Runs the job as the given tenant and returns its result; the job's exceptions pass through. */
    public static <T> T runAs(String tenant, Supplier<T> job) {
        String outer = TENANT.get();
        TENANT.set(tenant);
        try {
            return job.get();
        } finally {
            if (outer == null) {
                TENANT.remove();
            } else {
                TENANT.set(outer);
            }
        }
    }

    /**
     * Wraps a task that the current job hands to another thread (a pool, an async call), so that
     * the task runs as the tenant of the job that wrapped it.
     */
    public static Runnable wrap(Runnable task) {
        String tenant = current();
        return () -> runAs(tenant, () -> {
            task.run();
            return null;
        });
    }
}

package practice;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ExecutorService notifier = Executors.newSingleThreadExecutor();
            try {
                for (String tenant : new String[] {"oak-press", "river-hotel"}) {
                    AtomicReference<String> sentAs = new AtomicReference<>("not sent");
                    Runnable task = TenantContext.runAs(tenant, () -> TenantContext.wrap(() -> sentAs.set(TenantContext.current())));
                    notifier.submit(task).get(5, TimeUnit.SECONDS);
                    System.out.println("job " + tenant + " notified as: " + sentAs.get());
                }
                String plain = notifier.submit(TenantContext::current).get(5, TimeUnit.SECONDS);
                System.out.println("plain task on notifier sees: " + plain);
            } finally {
                notifier.shutdownNow();
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

